        {"id": "scr_close_dashboard", "name": "Financial Close Dashboard & Subledger Lock", "navigation": ["Applications", "Financial Close Management", "All", "Console"], "purpose": "Enforce strict accounting period cutoffs by locking subledgers sequentially to prevent unauthorized backdating.", "whyRecordsAreHere": ["Audit requirement. Once AP, AR, and Cash are verified, they must be locked so site teams cannot post late entries."], "keyFieldsAndFilters": [{"name": "Period", "description": "Target accounting month/year (e.g. 08/2026)."}, {"name": "Module Lock Status", "description": "Open, Staged, Closed, Locked."}], "accountantActionSOP": ["1. Lock AP Subledger on Day 3 of close after all vendor invoices are entered.", "2. Lock AR Subledger on Day 4 after rent roll and delinquency are balanced.", "3. Lock Cash Management after bank reconciliations tie to $0.00.", "4. Execute GL close diagnostic report to verify zero unposted batches.", "5. Lock General Ledger and request Controller sign-off."], "glAccountingImpact": "Locks Retained Earnings and Net Operating Income (NOI) against any further postings.", "whatHappensNext": "Period is permanently locked. Any subsequent adjustments must be booked in the following accounting month.", "yardiEquivalent": "Yardi Voyager: Financials > Closing > Post Month (AP/AR post month by property) and Year End Close; close tasks tracked via Task Runner/workflow checklists or a third-party close tool.", "pdfManualSource": "RP Financial Suite Financial Close Management User Guide.pdf, Pages 38-41 (Close Checklist Page), 67-70 (Console); RP Accounting General Ledger User Guide.pdf, Pages 54-55 (Closing Books from the G/L Workbench)", "proTips": "Never unlock a closed subledger without written authorization from the Financial Controller."}
